"use client";
// Complete Kashmiri keyboard: every letter, vowel sign and mark found in all our data
// (generated by scripts/build_keyboard.py into lib/ks-keyboard.json), whatever the font.
import { useState } from "react";
import data from "@/lib/ks-keyboard.json";

type Key = { c: string; group: "signs" | "letters" | "more"; n: number; name: string; code: string; label: string };
const KEYS = data.keys as Key[];
const GROUPS: [Key["group"], string][] = [["signs", "Vowel signs & marks"], ["letters", "Letters"], ["more", "Numbers & punctuation"]];

export function Keyboard({ onKey }: { onKey: (s: string) => void }) {
  const [group, setGroup] = useState<Key["group"]>("signs");
  return (
    <div className="kb" onMouseDown={(e) => e.preventDefault()}>
      <div className="kb-top">
        <div className="tabs" style={{ margin: 0 }}>
          {GROUPS.map(([g, label]) => (
            <button type="button" key={g} aria-pressed={group === g} onClick={() => setGroup(g)}>
              {label} <span className="muted">{KEYS.filter((k) => k.group === g).length}</span>
            </button>
          ))}
        </div>
        <div style={{ display: "flex", gap: 6 }}>
          <button type="button" className="key wide" onClick={() => onKey(" ")}>space</button>
          <button type="button" className="key wide" onClick={() => onKey("\b")}>⌫ delete</button>
        </div>
      </div>
      <div className="kb-grid" dir="rtl">
        {KEYS.filter((k) => k.group === group).map((k) => (
          <button type="button" key={k.c} className={"key" + (k.group === "signs" ? " mark" : "")}
            title={`${k.name} (${k.code})`} aria-label={k.label || k.name} onClick={() => onKey(k.c)}>
            <span className="ks">{k.group === "signs" ? "◌" + k.c : k.c === "‌" ? "|" : k.c}</span>
            {(k.label || k.group === "signs") && <small>{k.label || k.code}</small>}
          </button>
        ))}
      </div>
      <p className="muted small" style={{ margin: "6px 0 0" }}>Point at a key (or hold it on a phone) to see its Unicode name. Signs go after the letter they sit on.</p>
    </div>
  );
}
